function skorRisiko(kemungkinan, dampak) {
  const skor = kemungkinan * dampak;
  const tingkat = skor >= 15 ? "tinggi" : skor >= 8 ? "sedang" : "rendah";
  return { skor, tingkat };
}

function urutkanRisiko(daftar) {
  return daftar
    .map((r, i) => ({ nama: r.nama, skor: r.kemungkinan * r.dampak, i }))
    .sort((a, b) => b.skor - a.skor || a.i - b.i)
    .map((r) => r.nama);
}

