function caesar(teks, geser) {
  const g = ((geser % 26) + 26) % 26;
  return teks.replace(/[a-z]/gi, (c) => {
    const dasar = c <= "Z" ? 65 : 97;
    return String.fromCharCode(((c.charCodeAt(0) - dasar + g) % 26) + dasar);
  });
}

