solution.code:
function entropiBit(sandi) {
  let kumpulan = 0;
  if (/[a-z]/.test(sandi)) kumpulan += 26;
  if (/[A-Z]/.test(sandi)) kumpulan += 26;
  if (/[0-9]/.test(sandi)) kumpulan += 10;
  if (/[^a-zA-Z0-9]/.test(sandi)) kumpulan += 33;
  if (kumpulan === 0) return 0;
  return Math.round(sandi.length * Math.log2(kumpulan) * 10) / 10;
}

function kategoriSandi(bit) {
  if (bit < 40) return "lemah";
  if (bit < 60) return "sedang";
  if (bit < 80) return "kuat";
  return "sangat kuat";
}

