function redirectAman(next) {
  if (typeof next !== "string" || next === "") return "/dasbor";
  if (next[0] !== "/" || next[1] === "/") return "/dasbor";
  if (next.includes("\\") || /[\u0000-\u001f]/.test(next)) return "/dasbor";
  return next;
}

