function evaluasiFirewall(aturan, paket) {
  for (const a of aturan) {
    const portCocok = a.port === "any" || a.port === paket.port;
    const sumberCocok = a.sumber === "any" || paket.sumber.startsWith(a.sumber);
    if (a.protokol === paket.protokol && portCocok && sumberCocok) return a.aksi;
  }
  return "blokir";
}

