def domain_sah(url, domain_resmi):
    sisa = url.split("://", 1)[-1]
    for pemisah in "/?#":
        sisa = sisa.split(pemisah, 1)[0]
    host = sisa.split(":", 1)[0].lower()
    resmi = domain_resmi.lower()
    return host == resmi or host.endswith("." + resmi)

