solution.code:
function periksaSandi(sandi, { nama = "", umum = [] } = {}) {
  const masalah = [];
  const kecil = sandi.toLowerCase();
  if (sandi.length < 12) masalah.push("terlalu pendek");
  if (nama && kecil.includes(nama.toLowerCase())) masalah.push("memuat nama");
  if (umum.some((u) => u.toLowerCase() === kecil)) masalah.push("sandi umum");
  const kelas = [/[a-z]/, /[A-Z]/, /[0-9]/, /[^a-zA-Z0-9]/].filter((r) => r.test(sandi)).length;
  if (kelas < 3) masalah.push("kurang variasi");
  if (/(.)\1\1/.test(sandi)) masalah.push("karakter berulang");
  return { skor: Math.max(0, 100 - 20 * masalah.length), masalah, valid: masalah.length === 0 };
}

function laporanAkun(akun, umum) {
  const lemah = akun.filter((a) => !periksaSandi(a.sandi, { nama: a.nama, umum }).valid).map((a) => a.nama);
  const persen = akun.length ? Math.round((lemah.length / akun.length) * 100) : 0;
  return { total: akun.length, lemah, persen };
}

